(function(){'use strict';var e=document.querySelectorAll('.menu-toggle');var t=document.querySelectorAll('.menu');e.forEach(function(e){e.addEventListener('click',function(){var e=this.getAttribute('aria-expanded')==="true";this.setAttribute('aria-expanded',!e),document.querySelector('.menu').classList.toggle('active')})}),document.querySelectorAll('a[href^="#"]').forEach(function(e){e.addEventListener('click',function(t){var o=document.querySelector(e.getAttribute('href'));o&&(t.preventDefault(),document.documentElement.scrollTo({top:o.offsetTop,behavior:'smooth'}))})})})();